\label{asmp:EB_t-ell} 
There exist maps $t:{\cal  P}(\mathbb{Z}_+)\to \mathbb R$ and $\ell:\mathbb R^2\to\mathbb R$ such that, for any two probability mass functions $q_1,q_2\in{\cal  P}(\mathbb{Z}_+)$,
\begin{displaymath}
d(q_1\|q_2)=t(q_1)+\sum_{y\geq0}\ell(q_1(y),q_2(y)),
\end{displaymath}
where, for every $a>0$, the map $b\mapsto \ell(a,b)$ is strictly decreasing and strictly convex, and $\ell(0,b)=0$ for all $b\geq0$.

\label{def:coarsening}
For any probability mass function $p\in{\cal  P}(\mathbb{Z}_+)$ and any integer $T\geq0$, define the $T$-coarsening of $p$ by
\begin{equation}\label{eq:coarsening}
\widetilde p^{(T)}(y)=\begin{cases}
p(y) & 0\leq y\leq T,\\[0.2cm]
\sum_{j\geq T+1}p(j) & y=T+1.
\end{cases}
\end{equation}

\label{asmp:dist_sandwich}
There exist absolute constants $c_1,c_2>0$ such that, for any probability mass functions $q_1,q_2$ on $\mathbb{Z}_+$,
\begin{align}\label{eq:EB_Assupmtion_2}
c_1H^2(q_1,q_2)\leq d(q_1\|q_2)\leq c_2\chi^2(q_1\|q_2).
\end{align}

\label{lem:EB_density-H2}
Let $d$ satisfy Assumptions \ref{asmp:EB_t-ell}--\ref{asmp:dist_sandwich}, and let ${G^\ast}$ denote the data-generating mixing distribution. There exist constants $C_1,C_2$ such that the following holds for the minimum-$d$-distance estimate $\widehat G_{d,m}$ in ~(\ref{eq:optim-genr}), where the optimization is performed over an appropriate class given below:
\begin{enumerate}[label=(\alph*)~]
\item \label{pt:bounded-regular-dens}  Let $\mathcal C\subset {\cal  P}[0,\widehat h]$ be a convex and weakly closed class. If ${G^\ast}\in{\cal  P}[0,h]\cap\mathcal C$ with $h\leq\widehat h$ and $\widehat G_{d,m}$ is optimized over the class $\mathcal C$, then for any $m\geq3$
\begin{displaymath}
\mathbb{E}\left[ H^2(f_{{G^\ast}},f_{{\widehat G_{d,m}}}) \right]\leq {C_1\@@over m}\min\left\{ \max\{1,\widehat h\}{\log m\@@over \log\log m},\widehat h+\log m \right\};
\end{displaymath}
\item \label{pt:subexpo-regular-dens} Let $\mathcal C\subset {\sf SubE}(s)$ be a convex and weakly closed class. If ${G^\ast}\in\mathcal C$ and $\widehat G_{d,m}$ is optimized over the class $\mathcal C$, then for any $m\geq2$
\begin{displaymath}
\mathbb{E}\left[ H^2(f_{{G^\ast}},f_{{\widehat G_{d,m}}}) \right]\leq {C_2\max\{1,s\}\@@over m}{\log m}.
\end{displaymath} 
\end{enumerate}

\label{lem:EB_density-H2_coars}
Let $d$ satisfy Assumptions \ref{asmp:EB_t-ell}--\ref{asmp:dist_sandwich}, and let ${G^\ast}$ denote the data-generating mixing distribution. Consider the $T$-coarsened minimum-$d$-distance estimate $\widetilde G_{d,m}^{(T)}$ of ${G^\ast}$ obtained from a training sample of size $m$, with $T\geq0$.
\begin{enumerate}[label=(\alph*)~]
\item \label{pt:bounded-coarse} Let $\mathcal C\subset {\cal  P}[0,\widehat h]$ be a convex and weakly closed class. If ${G^\ast}\in{\cal  P}[0,h]\cap\mathcal C$ with $h\leq \widehat h$ and $\widetilde G_{d,m}^{(T)}$ is optimized over $\mathcal C$, then for every $T\geq 0$ and $m\geq 3$,
\begin{align}
\mathbb E\Big[H^2\big(\widetilde f_{{G^\ast}}^{(T)},\,\widetilde f_{\widetilde
G^{(T)}_{d,m}}^{(T)}\big)\Big]
&\le \frac{1}{m}\min\Big\{\frac{4c_2}{c_1}(T+2),\
\Big(\frac{12c_2}{c_1}+4\Big)
(\widehat h e^2+2)\frac{2\log
m}{\log\log m}\Big\},
\label{eq:final-bounded}
\end{align}
\item Let $\mathcal C\subset {\sf SubE}(s)$ be a convex and weakly closed class. If ${G^\ast}\in\mathcal C$ and $\widetilde G_{d,m}^{(T)}$ is optimized over $\mathcal C$, then for every $T\geq 0$ and $m\geq \mathop{\rm exp}\left(\frac 1 2 \log(1+\frac{1}{2s})\right)$
\begin{align}
\mathbb E\Big[H^2\big(\widetilde f_{{G^\ast}}^{(T)},\,\widetilde f_{\widetilde
G^{(T)}_{d,m}}^{(T)}\big)\Big]
&\le \frac{1}{m}\min\Big\{\frac{4c_2}{c_1}(T+2),\
\Big(\frac{16c_2}{c_1}+6\Big)\frac{2\log m}{\log(1+1/(2s))}\Big\}.
\label{eq:final-subexp}
\end{align}
\end{enumerate}

\label{th:consist1}
Let ${G^\ast}$ denote the data-generating mixing distribution, and let $d$ satisfy Assumptions \ref{asmp:EB_t-ell} and \ref{asmp:dist_sandwich}. The following asymptotic results hold for the minimum-$d$-distance estimator $\widehat G_{d,m_n}$ defined in ~(\ref{eq:optim-genr}), based on an independent training sample of size $m_n$ and with the optimization performed over a class $\mathcal C$ specified below.
\begin{enumerate}[label=(\alph*)~]
\item Suppose that $\mathcal C$ is a convex and weakly closed subset of ${\sf SubE}(s)$, ${G^\ast}\in\mathcal C$, $m_n\to\infty$ as $n\to\infty$, $\theta\mapsto u(x,\theta)$ is $G$-almost surely continuous for every $x$ and every $G\in\mathcal C$, and condition ~(\ref{eq:condition2}) holds. Then,
\begin{displaymath}
\frac{1}{n}\bigl(S_n-\widehat S_n(\widehat G_{d,m_n})\bigr)\stackrel{\mathbb{P}}{\rightarrow}0.
\end{displaymath}
\item Suppose that $\mathcal C$ is a convex and weakly closed subset of $\mathcal P(\Theta_J)$ such that $G(\{0\})\leq a_0$ for some $a_0<1$ and every $G\in \mathcal C$, ${G^\ast}\in\mathcal C$, $m_n\asymp n$, and there exist constants $c$ and $M$ such that $u(x,\theta_j)=c$ for every $j=1,\ldots,J$ and every $x>M$. Then,
\begin{displaymath}
\frac{1}{n}\bigl(S_n-\widehat S_n(\widehat G_{d,m_n})\bigr)=O_{\mathbb P}(n^{-1/2}(\log n)^{1/2}).
\end{displaymath}
\end{enumerate}

\label{th:consist2}
Let ${G^\ast}$ denote the data-generating mixing distribution, and let $d$ satisfy Assumptions \ref{asmp:EB_t-ell} and \ref{asmp:dist_sandwich}. The following asymptotic results hold for the coarsened minimum-$d$-distance estimator $\widetilde G^{(T_n)}_{d,m_n}$, based on an independent training sample of size $m_n\to\infty$ and with the optimization performed over a class $\mathcal C$ specified below.
\begin{enumerate}[label=(\alph*)~]
    \item Suppose that $\mathcal C$ is a convex and weakly closed subset of ${\sf SubE}(s)$,  ${G^\ast}\in\mathcal C$, $T_n\ge  \max\left\{1,\frac{2}{\log(1+1/(2s))}\right\}\log m_n$ for $n$ sufficiently large, $\theta\mapsto u(x,\theta)$ is $G$-almost surely continuous for every $x$ and every $G\in\mathcal C$, and condition ~(\ref{eq:condition2}) holds. Then, as $n\to\infty$,
\begin{displaymath}
   \frac{ S_n-\widehat S_n(\widetilde G^{(T_n)}_{d,m_n})}{n}\stackrel{\mathbb{P}}{\rightarrow}0.
\end{displaymath}
     \item  Suppose that $\mathcal C$ is a convex and weakly closed subset of $\mathcal P(\Theta_J)$  such that $G(\{0\})\leq a_0$ for some $a_0<1$ and every $G\in \mathcal C$, $T_n\rightarrow\infty$,
    $m_n\asymp n$, and there exist constants $c$ and $M$ such that $u(x,\theta_j)=c$ for every $j=1,\dots,J$ and every $x>M$. Then, as
$n\to\infty$,
\begin{displaymath}
   \frac{ S_n-\widehat S_n(\widetilde G^{(T_n)}_{d,m_n})}{n} =O_{\mathbb{P}}(n^{-1/2}(\log n)^{1/2}).
\end{displaymath}
\end{enumerate}

\label{def_ratio}
For any probability measure $G$ on $\mathbb{R}_+$, define $m_G(x):=\frac{A_x(G)}{B_x(G)}$, where
\begin{displaymath}
A_x(G)=\int_{\mathbb{R}_+} e^{-\theta}\theta^x I(\theta<x)\,dG(\theta),\qquad B_x(G)=\int_{\mathbb{R}_+} e^{-\theta}\theta^x\,dG(\theta)=x!\,f_G(x).
\end{displaymath}
Whenever $B_x(G)>0$, the ratio $m_G(x)=A_x(G)/B_x(G)$ has its usual conditional-probability interpretation. If $B_x(G)=0$, we define $m_G(x)$ by the deterministic value of the event $\{\theta<x\}$ whenever this event is $G$-almost surely constant. Thus, we set $m_G(x)=1$ if $G([0,x))=1$ and $m_G(x)=0$ if $G([x,\infty))=1$. This convention is used only outside the relevant finite window, where the posterior event is deterministic under the support constraint.

\label{def_smooth}
Fix $\delta\in(0,1]$. Define $\phi_\delta:\mathbb R\to[0,1]$ by
\begin{displaymath}
\phi_\delta(u):=
\begin{cases}
1, & u\ge \delta,\\[1mm]
\frac{u+\delta}{2\delta}, & |u|<\delta,\\[2mm]
0, & u\le -\delta.
\end{cases}
\end{displaymath}

\label{asmp:aa-self-normal-regular}
For each $x\in\mathcal W_+$ and each $\delta\in(0,1]$, there exist coefficients 
$\alpha_{x,\delta}(t)$, $t\in\mathbb{Z}_+$, and a remainder bound 
$\varepsilon_{x,\delta}\geq0$ such that, for all $G\in\mathcal C$,
\begin{equation}\label{eq:A-rep-regular-aa}
\left|A_{x,\delta}(G)-\sum_{t\geq0}\alpha_{x,\delta}(t)f_G(t)\right|\leq\varepsilon_{x,\delta},
\end{equation}
and
\begin{equation}\label{eq:A-rep-eps-regular-aa}
\varepsilon_{x,\delta}\leq C_\varepsilon |{\cal  W}_+| \delta,\qquad\delta\in(0,1],
\end{equation}
uniformly over $x\in\mathcal W_+$, with constants depending only on the structural parameters of the class $\mathcal C$.
Moreover, for all $G_1,G_2\in\mathcal C$,
\begin{equation}\label{eq:A-selfnorm-regular-aa}
\sum_{t\geq0}\alpha_{x,\delta}(t)^2\left(f_{G_1}(t)+f_{G_2}(t)\right)\leq C_A\left(A_{x,\delta}(G_1)+A_{x,\delta}(G_2)\right).
\end{equation}

\label{asmp:aa-self-normal-coarse}
For each $x\in\mathcal W_+$ and each $\delta\in(0,1]$, there exist coefficients $\alpha_{x,\delta}^{(T)}(t)$, $t=0,\ldots,T+1$, and a remainder bound $\varepsilon_{x,\delta}^{(T)}\geq0$ such that, for all $G\in\mathcal C$,
\begin{equation}\label{eq:A-rep-coarse-aa}
\left|A_{x,\delta}(G)-\sum_{t=0}^{T+1}\alpha_{x,\delta}^{(T)}(t)\widetilde f_G^{(T)}(t)\right|\leq\varepsilon_{x,\delta}^{(T)},
\end{equation}
and
\begin{equation}\label{eq:A-rep-eps-coarse-aa}
\varepsilon_{x,\delta}^{(T)}\leq C_\varepsilon h(T,|{\cal  W}_+|) \delta,\qquad\delta\in(0,1],
\end{equation}
uniformly over $x\in\mathcal W_+$, where $C_\varepsilon$ depends only on the structural parameters of the class $\mathcal C$, and $h(T,|\mathcal W_+|)>0$ satisfies $h(T,|\mathcal W_+|)\leq|\mathcal W_+|$. Moreover, for all $G_1,G_2\in\mathcal C$,
\begin{equation}\label{eq:A-selfnorm-coarse-aa}
\sum_{t=0}^{T+1}\left(\alpha_{x,\delta}^{(T)}(t)\right)^2\left(\widetilde f_{G_1}^{(T)}(t)+\widetilde f_{G_2}^{(T)}(t)\right)\leq C_A\left(A_{x,\delta}(G_1)+A_{x,\delta}(G_2)\right),
\end{equation}
with $C_A$ depending only on the structural parameters of the class $\mathcal C$.

\label{thm:main-above-average}
Let ${G^\ast}$ denote the data-generating mixing distribution. Consider the regular minimum-$d$-distance estimate $\widehat G_{d,m}$ of ${G^\ast}$ obtained from an independent training sample of size $m$.
\begin{enumerate}[label=(\alph*)]
\item Let $\widehat h>0$ and $\widehat K=\lfloor\widehat h\rfloor$. Let $\mathcal C\subseteq\mathcal P([0,\widehat h])$ be a convex and weakly closed class such that \prettyref{asmp:aa-local-mass} and
\prettyref{asmp:aa-self-normal-regular} hold on the window $\{0,\ldots,\widehat K\}$. Assume that ${G^\ast}\in\mathcal P([0,h])\cap\mathcal C$ for some $h\leq\widehat h$. Then there exist constants $C_0,C_1$, depending only on $(\widehat h,L)$ and the constants in \prettyref{asmp:aa-self-normal-regular}, such that, for every $\delta\in(0,1]$ and every $m\geq3$,
\begin{align}\label{eq:main-compact-result}
&\mathbb{E}\!\left[\left(\frac{\widehat S_{n,>}(\widehat G_{d,m})-\widehat S_{n,>}({G^\ast})}{\sqrt n}\right)^2\right]\\
&\notag\quad\le nC_0\delta+nC_1 C_d(\widehat h,c_1,c_2)\,\frac{1}{m}\min\!\left\{\max\{1,\widehat h\}\frac{\log m}{\log\log m},
\widehat h+\log m\right\}.
\end{align}
\item Let $K\geq0$ be an integer. Let $\mathcal C\subseteq{\sf SubE}(s)$ be a convex and weakly closed class such that \prettyref{asmp:aa-local-mass} and \prettyref{asmp:aa-self-normal-regular}
hold on the window $\{0,\ldots,K\}$. Assume that ${G^\ast}\in\mathcal C$. Then there exist constants $C_0,C_1$, depending only on $L$ and the constants in \prettyref{asmp:aa-self-normal-regular}, such that, for every $\delta\in(0,1]$ and every $m\geq2$,
\begin{equation}\label{eq:main-sube-result}
\mathbb{E}\!\left[\left(\frac{\widehat S_{n,>}(\widehat G_{d,m})-\widehat S_{n,>}({G^\ast})}{\sqrt n}\right)^2\right]\le nC_0K\delta+nC_1 C_d(s,c_1,c_2)\frac{\log m}{m}+nC_s e^{-c_sK},
\end{equation}
where one may take $c_s:=\log\left(1+\frac{1}{2s}\right)$ and $C_s:=3$.
\end{enumerate}

\label{thm:main-above-average-coarsened}
Let ${G^\ast}$ denote the data-generating mixing distribution. Consider the $T$-coarsened minimum-$d$-distance estimate $\widetilde G_{d,m}^{(T)}$ of ${G^\ast}$ obtained from an independent training sample of size $m$.
\begin{enumerate}[label=(\alph*)]
\item Let $\widehat h>0$, \(\widehat K=\lfloor\widehat h\rfloor\) and $T\geq \widehat  K$. Let $\mathcal C\subseteq\mathcal P([0,\widehat h])$ be a convex and weakly closed class such that \prettyref{asmp:aa-local-mass} and \prettyref{asmp:aa-self-normal-coarse} hold on the window $\{0,\ldots,\widehat K\}$. Assume that ${G^\ast}\in \mathcal P([0,h])\cap\mathcal C $ for some $h\leq \widehat h$. Then there exist constants \(C_0,C_1\), depending only on $(\widehat h,T,L)$ and the constants in \prettyref{asmp:aa-local-mass} and \prettyref{asmp:aa-self-normal-coarse}, such that, for every \(\delta\in(0,1]\) and every $m\ge3$,
\begin{equation}\label{eq:main-coarse-compact-result}
\mathbb{E}\!\left[\left(\frac{\widehat{S}_{n,>}(\widetilde {G}^{(T)}_{d,m})-\widehat{S}_{n,>}({G^\ast})}{\sqrt{n}}\right)^2\right]\le nC_0\delta+nC_1 C_d^{\mathrm{coarse}}(c_1,c_2)\frac{T+2}{m},
\end{equation}
where $C_d^{\mathrm{coarse}}(c_1,c_2)=\dfrac{4c_2}{c_1}$.
\item Let $K\geq 0$ and $T\geq K$. Let $\mathcal C\subseteq{\sf SubE}(s)$ be a convex and weakly closed class such that \prettyref{asmp:aa-local-mass} and
\prettyref{asmp:aa-self-normal-coarse} hold on the window $\{0,\ldots,K\}$. Assume that ${G^\ast}\in\mathcal C $. Then there exist constants \(C_0,C_1\), depending only on $(s,L)$ and the constants in \prettyref{asmp:aa-self-normal-coarse}, such that, for every \(\delta\in(0,1]\) and every $m\geq \max\{2,\mathop{\rm exp}\left(\frac 1 2 \log(1+\frac{1}{2s})\right)\}$,
\begin{align}\label{eq:main-coarse-sube-result}
&\mathbb{E}\!\left[\left(\frac{\widehat{S}_{n,>}(\widetilde {G}^{(T)}_{d,m})-\widehat{S}_{n,>}({G^\ast})}{\sqrt{n}}\right)^2\right]\\
&\notag\quad\le nKC_0\delta+nC_s e^{-c_sK}+n C_1C_d^{\mathrm{coarse}}(c_1,c_2)\min\{\frac{T+2}{m},{\log m\@@over m}\},
\end{align}
where one may take $c_s=\log\left(1+\frac1{2s}\right)$ and $C_s=3$. 
\end{enumerate}

\label{corr:above-average-discrete-feasible}
Set $K_J:=\lfloor \theta_J\rfloor$ and $T_J:=\max\{K_J,J-1\}$. Let $\mathcal C\subseteq\mathcal P(\Theta_J)$ be a convex and weakly closed class such that $\min_{0\le x\le K_J} f_G(x)\ge b_J$ for every $G\in\mathcal C$, where $b_J>0$. Assume that $d$ satisfies Assumptions \ref{asmp:EB_t-ell}--\ref{asmp:dist_sandwich}, and let ${G^\ast}\in \mathcal C$. Consider the regular minimum-$d$-distance estimate $\widehat G_{d,m}$ of ${G^\ast}$ and the $T$-coarsened minimum-$d$-distance estimate $\widetilde G_{d,m}^{(T)}$ of ${G^\ast}$ obtained from a training sample of size $m$.
\begin{enumerate}[label=(\alph*)]
\item There exists a constant $C_{\Theta_J}<\infty$, depending only on $(\Theta_J,b_J,c_1,c_2)$, such that for every $m\geq3$,
\begin{equation}\label{eq:above-average-discrete-regular}
\mathbb{E}\!\left[\left(\frac{\widehat S_{n,>}(\widehat G_{d,m})-\widehat S_{n,>}({G^\ast})}{\sqrt n}\right)^2\right]\le C_{\Theta_J}\,\frac{n\log m}{m}.
\end{equation}
\item Let \(T\ge T_J\). Then there exists a constant \(C_{{\Theta_J},T}<\infty\), depending only on
\(({\Theta_J},T,b_J,c_1,c_2)\), such that for every $m\geq 3$,
\begin{equation}\label{eq:above-average-discrete-coarsened}
\mathbb{E}\!\left[\left(\frac{\widehat S_{n,>}(\widetilde G_{d,m}^{(T)})-\widehat S_{n,>}({G^\ast})}
{\sqrt n}\right)^2\right]\le C_{{\Theta_J},T}\,\frac{n(T+2)}{m}.
\end{equation}
\end{enumerate}

\label{prop:poisson}
Let $m,n\geq1$. Let $X'_1,\ldots,X'_m$ be an independent training sample, with $X'_j\mid\theta'_j\stackrel{\mbox{\scriptsize{ind}}}{\sim} \operatorname{Poisson}(\cdot\mid\theta'_j)$ and $\theta'_j\stackrel{\mbox{\scriptsize{iid}}}{\sim} {G^\ast}_\tau$ for $j=1,\ldots,m$, and let $(X_{1},Y_{1},\theta_{1}),\ldots,(X_{n},Y_{n},\theta_{n})$ be the main sample distributed as in ~(\ref{model_distr_poi}), independently of $X'_{1:m}=(X'_1,\ldots,X'_m)$. Assume that ${G^\ast}_\tau$ is an Exponential distribution with rate $\tau$. Then the oracle Bayes estimates of $S_{n,\kappa}$ and
$S^{\text{\tiny{[Pred]}}}_{n,\kappa}$ are
\begin{equation}\label{eq:par_tot}
\widehat{S}_{n,\kappa}({G^\ast}_\tau)= \widehat{S}^{\text{\tiny{[Pred]}}}_{n,\kappa}({G^\ast}_\tau)=\sum_{i=1}^{n}\frac{1+X_i}{1+\tau}I(X_i\leq\kappa),
\end{equation}
whereas the oracle Bayes estimates of $S_{n,>}$ and $S^{\text{\tiny{[Pred]}}}_{n,>}$ are
\begin{equation}\label{eq:par_above}
\widehat{S}_{n,>}({G^\ast}_\tau)=n-\sum_{i=1}^{n}\frac{\Gamma(1+X_i,(1+\tau)X_i)}{\Gamma(1+X_i)},
\end{equation}
and
\begin{equation}\label{eq:par_above_pred}
\widehat{S}^{\text{\tiny{[Pred]}}}_{n,>}({G^\ast}_\tau)=\sum_{i=1}^{n}\left[1-(1+\tau)^{-X_i}\right],
\end{equation}
respectively, where $\Gamma(x)=\int_{\mathbb R_+}y^{x-1}e^{-y}\,dy$ and $\Gamma(x,z)=\int_z^\infty y^{x-1}e^{-y}\,dy$. The rate parameter $\tau$ is estimated from the training sample $X'_{1:m}$. In particular, the maximum-likelihood estimate of $\tau$ is
\begin{displaymath}
\widehat{\tau}^{\text{\tiny{[ML]}}}_{m}=\frac{m}{\sum_{j=1}^{m}X'_j}.
\end{displaymath}
Accordingly, the resulting parametric maximum-likelihood estimates of $S_{n,\kappa}$ and $S_{n,>}$, together with those of their predictive counterparts, are obtained by replacing $\tau$ in ~(\ref{eq:par_tot})--~(\ref{eq:par_above_pred}) with its estimate $\widehat{\tau}^{\text{\tiny{[ML]}}}_{m}$. If, instead, a Beta prior distribution with hyperparameters $(\alpha,\beta)$ is placed on $\tau/(1+\tau)$, then the corresponding Bayes estimate of $\tau$ based on the training sample $X'_{1:m}$ is
\begin{displaymath}
\widehat{\tau}^{\text{\tiny{[B]}}}_{m}=\frac{m+\alpha}{\beta+\sum_{j=1}^{m}X'_j}.
\end{displaymath}
Accordingly, the resulting parametric Bayes estimates of $S_{n,\kappa}$ and $S_{n,>}$, together with those of their predictive counterparts, are obtained by replacing $\tau$ in ~(\ref{eq:par_tot})--~(\ref{eq:par_above_pred}) with its estimate $\widehat{\tau}^{\text{\tiny{[B]}}}_{m}$.

\label{lmm:subexpo_properties}
	Given any $s>0$ and ${G^\ast}\in{\sf SubE}(s)$, the following are satisfied.
	\begin{enumerate}[label=(\roman*)~]
		\item \label{pt:i} If $\theta\sim {{G^\ast}}$, then $\mathbb{E}[\theta^4]\leq 12s^4$.
		\item \label{pt:ii} If $\left\{ Z_i \right\}_{i=1}^m{\stackrel{\text{iid\xspace}}{\sim}} f_{{G^\ast}}$, then for any $K\geq 1$
		\begin{align}
			\label{eq:EB_prop_mixture}
			\mathbb{P}\left[ Z_1\geq K \right]
			\leq 3 e^{-K\log\left( 1+\frac 1{2s} \right)},
			\quad
			\mathbb{E}\left[ Z_{(m)}^4 \right]\leq {64(\log m)^4+90\@@over \left( \log\left( 1+\frac 1{2s} \right) \right)^4}.
		\end{align}
	\end{enumerate}

\label{lem:E0}
Let $d$ satisfy Assumptions \ref{asmp:EB_t-ell} and \ref{asmp:dist_sandwich}, and let ${G^\ast}$ denote the mixing measure of the data-generating distribution. 
Let  $\widetilde G^{(T)}_{d,m}$ be the $T$-coarsened minimum-$d$-distance estimate of ${G^\ast}$ defined in~(\ref{eq:optim-coarse}), where the optimization is performed over an appropriate class as in
Lemma~\ref{lem:EB_density-H2}. Then, 
\begin{equation}
\label{eq:E0-main}
\mathbb E\Big[H^2\big(\widetilde f_{{G^\ast}}^{(T)},\,\widetilde f_{\widehat
G^{(T)}_{d,m}}^{(T)}\big)\Big]
\;\le\;\left\{
\begin{array}{ll}
\frac{4c_2}{c_1}\,\frac{J}{m}+\Big(\frac{4c_2}{c_1}+2m\Big)\,\mathbb P_{X\sim f_{{G^\ast}}}[X\ge J]& 1\le J\le T+1\\
\frac{4c_2}{c_1}\,\frac{J}{m} & J=T+2.
\end{array}
\right.
\end{equation}

Denote $H=\operatorname{Unif}[a,b]$.

\noindent
    (a) We can write
\begin{align*}
    H^2(f_{0,\varepsilon},f_{1,\varepsilon})&=\sum_{t\geq 0}\left(\sqrt{f_{0,\varepsilon}(t)}-\sqrt{f_{1,\varepsilon}(t)}\right)^2\\
    &\leq \sum_{t\geq 0}\frac{\left(f_{0,\varepsilon}(t)-f_{1,\varepsilon}(t)\right)^2}{f_{0,\varepsilon}(t)+f_{1,\varepsilon}(t)}\\
   & \leq c^2 \sum_{t\geq 0}\frac{\left(\int_{1-\varepsilon}^1 p_\theta(t)d\theta-\int_{1}^{1+\varepsilon}p_\theta(t)d\theta\right)^2}{f_{0,\varepsilon}(t)+f_{1,\varepsilon}(t)}\\
   &\leq c^2 \varepsilon^2\sum_{t\geq 0}\frac{\left(
   \int_0^1 ( p_{1-\varepsilon+\varepsilon s}(t)-
    p_{1+\varepsilon s}(t)   d s\right)^2}{
    k_1  {a^t}/{t!}}\end{align*}
    for a constant $k_1$, where the first inequality comes from
    $$
    (\sqrt u -\sqrt v)^2=\frac{(u-v)^2}{(\sqrt u+\sqrt v)^2}\leq 
    \frac{(u-v)^2}{u+v}
    $$
for $u,v>0$, and the last inequality comes from
$$
f_{0,\varepsilon}(t)+f_{1,\varepsilon}(t)\geq \frac{2(1-c\varepsilon_0)}{b-a}\int_a^b \frac{e^{-\theta}\theta^t}{t!}d\theta\geq \frac{e^{-b}a^t}{t!}:=k_1\frac{a^t}{t!}.
$$
By the fundamental theorem of calculus
\begin{align*}
    \int_0^1 ( p_{1-\varepsilon+\varepsilon s}(t)-
    p_{1+\varepsilon s}(t) )  d s&=-
    \int_0^1\int_{1+\varepsilon s -\varepsilon}^{1+\varepsilon s}\frac{\partial p_\theta(t)}{\partial \theta}d\theta ds\\
    &=- \int_0^1\int_{1+\varepsilon s -\varepsilon}^{1+\varepsilon s}
    p_\theta(t)\left(\frac t \theta -1\right)d\theta ds.
\end{align*}
Thus,
\begin{align*}
     H^2(f_{0,\varepsilon},f_{1,\varepsilon})
     &\leq \frac{c^2}{k_1}  \varepsilon^2 \sum_{t\ge 0} 
     \frac{\left(\int_0^1\int_{1+\varepsilon s -\varepsilon}^{1+\varepsilon s}
    p_\theta(t)\left(\frac t \theta -1\right)d\theta ds\right)^2}{{a^t}/{t!}}\\
    &\leq \frac{c^2}{k_1}  \varepsilon^2 \sum_{t\ge 0} 
     \frac{\left(\int_0^1\int_{1+\varepsilon s -\varepsilon}^{1+\varepsilon s}
   \frac{e^{-\theta}\theta^t}{t!}\left(\frac t \theta -1\right)d\theta ds\right)^2}{{a^t}/{t!}}\\
   &\leq \frac{c^2}{k_1}  \varepsilon^2 \sum_{t\ge 0} 
     \frac{\left(\int_0^1\int_{1+\varepsilon s -\varepsilon}^{1+\varepsilon s}
   \left(\frac{e^{-\theta}\theta^t}{t!}+t\frac{e^{-\theta}\theta^{t-1}}{t!}\right)d\theta ds\right)^2}{{a^t}/{t!}}.
\end{align*}
For $s\in [0,1]$ and $\theta\in [1+\varepsilon s -\varepsilon,1+\varepsilon s]$, $\theta\in [1-\varepsilon_0,1+\varepsilon_0]$, which implies
\begin{align*}
H^2(f_{0,\varepsilon},f_{1,\varepsilon})
     &\leq \frac{c^2}{k_1^2}  e^{-2(1-\varepsilon_0)}\varepsilon^4 \left[  
    \sum_{t\ge 0} 
     \frac{\left(1+\varepsilon_0\right)^{2t}}{a^t}
     +\sum_{t\ge 0} \frac{t^2\left(1+\varepsilon_0\right)^{2(t-1)}}{a^t}\right]\\
     &\leq C_1\varepsilon^4,
\end{align*}
for a constant $C_1$.

