\label{lem:ratio-stab}
Let $A,B,\widetilde A,\widetilde B\ge 0$ with $B>0$, $\widetilde B>0$, and $A\le B$, $\widetilde A\le \widetilde B$. Then
\begin{displaymath}
\frac{B\widetilde B}{B+\widetilde B}\Big(\frac{A}{B}-\frac{\widetilde A}{\widetilde B}\Big)^2\le 8\Big\{(\sqrt A-\sqrt{\widetilde A})^2+(\sqrt B-\sqrt{\widetilde B})^2\Big\}.
\end{displaymath}

Set $a=\sqrt A$, $b=\sqrt B$, $\widetilde a=\sqrt{\widetilde A}$, and $\widetilde b=\sqrt{\widetilde B}$.  Since $A\le B$ and $\widetilde A\le \widetilde B$, we have $0\le a\le b$ and $0\le \widetilde a\le \widetilde b$. 
Now
\begin{displaymath}
\frac{A}{B}-\frac{\widetilde A}{\widetilde B}=\Big(\frac{a}{b}\Big)^2-\Big(\frac{\widetilde a}{\widetilde b}\Big)^2=\Big(\frac{a}{b}-\frac{\widetilde a}{\widetilde b}\Big)\Big(\frac{a}{b}+\frac{\widetilde a}{\widetilde b}\Big).
\end{displaymath}
Because $a/b,\widetilde a/\widetilde b\in[0,1]$, we have $\frac{a}{b}+\frac{\widetilde a}{\widetilde b}\le 2$. Therefore $\Big(\frac{A}{B}-\frac{\widetilde A}{\widetilde B}\Big)^2\le4\Big(\frac{a}{b}-\frac{\widetilde a}{\widetilde b}\Big)^2$. Multiplying by $\frac{B\widetilde B}{B+\widetilde B}=\frac{b^2\widetilde b^2}{b^2+\widetilde b^2}$ gives
\begin{displaymath}
\frac{B\widetilde B}{B+\widetilde B}\Big(\frac{A}{B}-\frac{\widetilde A}{\widetilde B}\Big)^2\le4\cdot \frac{b^2\widetilde b^2}{b^2+\widetilde b^2}\Big(\frac{a}{b}-\frac{\widetilde a}{\widetilde b}\Big)^2=4\cdot \frac{(a\widetilde b-\widetilde a b)^2}{b^2+\widetilde b^2}.
\end{displaymath}
Next, decompose $a\widetilde b-\widetilde a b=(a-\widetilde a)\widetilde b+\widetilde a(\widetilde b-b)$. Hence, by $(u+v)^2\le 2u^2+2v^2$, $(a\widetilde b-\widetilde a b)^2\le2(a-\widetilde a)^2\widetilde b^2+2\widetilde a^2(\widetilde b-b)^2$. Since $\widetilde a\le \widetilde b$, this yields
\begin{displaymath}
(a\widetilde b-\widetilde a b)^2\le2(a-\widetilde a)^2\widetilde b^2+2\widetilde b^2(\widetilde b-b)^2.
\end{displaymath}
Divide by $b^2+\widetilde b^2\ge \widetilde b^2$:
\begin{displaymath}
\frac{(a\widetilde b-\widetilde a b)^2}{b^2+\widetilde b^2}\le2(a-\widetilde a)^2+2(\widetilde b-b)^2.
\end{displaymath}
Substituting back gives
\begin{displaymath}
\frac{B\widetilde B}{B+\widetilde B}\Big(\frac{A}{B}-\frac{\widetilde A}{\widetilde B}\Big)^2\le8(a-\widetilde a)^2+8(\widetilde b-b)^2=8\Big\{(\sqrt A-\sqrt{\widetilde A})^2+(\sqrt B-\sqrt{\widetilde B})^2\Big\}.
\end{displaymath}
This proves the lemma.

\label{lem:quad-convert}
For any $a,b\ge 0$ (with the convention $0/0=0$),
\begin{displaymath}
a \le 4\,\frac{ab}{a+b} + 2\,\frac{(a-b)^2}{a+b}.
\end{displaymath}
Consequently, for any $u\in[0,1]$,
\begin{displaymath}
a\,u \le 4\,\frac{ab}{a+b}\,u + 2\,\frac{(a-b)^2}{a+b}.
\end{displaymath}

If $a+b=0$, then $a=b=0$ and the inequality is trivial. Assume now $a+b>0$. Multiplying the desired inequality by $(a+b)$, it is enough to prove that $a(a+b)\le 4ab+2(a-b)^2$. Expand the right-hand side: $4ab+2(a-b)^2=4ab+2(a^2-2ab+b^2)=2a^2+2b^2$. So it suffices to prove that $a(a+b)\le 2a^2+2b^2$. But
\begin{displaymath}
2a^2+2b^2-a(a+b)=a^2-ab+2b^2.
\end{displaymath}
Now $a^2-ab+2b^2=\frac12(a-b)^2+\frac12 a^2+\frac32 b^2\ge 0$. Hence $a(a+b)\le 2a^2+2b^2=4ab+2(a-b)^2$, which proves
\begin{displaymath}
a \le 4\,\frac{ab}{a+b}+2\,\frac{(a-b)^2}{a+b}.
\end{displaymath}
For the second statement, simply multiply both sides by $u\in[0,1]$ and use $u\le 1$:
\begin{displaymath}
a\,u\le4\,\frac{ab}{a+b}\,u+2\,\frac{(a-b)^2}{a+b}\,u\le4\,\frac{ab}{a+b}\,u+2\,\frac{(a-b)^2}{a+b}.
\end{displaymath}
This proves the lemma.

\label{lem:chi2-hell}
For any $a,b\ge 0$ (with $0/0=0$),
\begin{displaymath}
\frac{(a-b)^2}{a+b}\le 4(\sqrt a-\sqrt b)^2.
\end{displaymath}
Hence for pmfs $p,q$ on a countable alphabet,
\begin{displaymath}
\sum_t \frac{(p(t)-q(t))^2}{p(t)+q(t)}\le4\sum_t(\sqrt{p(t)}-\sqrt{q(t)})^2.
\end{displaymath}

If $a=b=0$, the claim is trivial. Otherwise, use $a-b=(\sqrt a-\sqrt b)(\sqrt a+\sqrt b)$, so $(a-b)^2=(\sqrt a-\sqrt b)^2(\sqrt a+\sqrt b)^2$. Since $(\sqrt a+\sqrt b)^2=a+b+2\sqrt{ab}\le 2(a+b)$, we obtain
\begin{displaymath}
(a-b)^2\le 2(a+b)(\sqrt a-\sqrt b)^2.
\end{displaymath}
In fact this already gives the sharper bound with constant \(2\); hence certainly $\frac{(a-b)^2}{a+b}\le 4(\sqrt a-\sqrt b)^2$. Summing the pointwise inequality with $a=p(t)$ and $b=q(t)$ yields
\begin{displaymath}
\sum_t \frac{(p(t)-q(t))^2}{p(t)+q(t)}\le4\sum_t(\sqrt{p(t)}-\sqrt{q(t)})^2.
\end{displaymath}
This proves the lemma.

\label{lem:sqrtA-control-route1-hhat}
Fix \(x\in\mathcal W_+\) and \(\delta\in(0,1]\). Assume \prettyref{asmp:aa-self-normal-regular} holds on \(\mathcal C\). Then, for all \(G_1,G_2\in\mathcal C\),
\begin{displaymath}
\big(\sqrt{A_{x,\delta}(G_1)}-\sqrt{A_{x,\delta}(G_2)}\big)^2\le 8C_A\,\mathcal H(G_1,G_2)+2\sqrt{2}\,\varepsilon_{x,\delta}.
\end{displaymath}

Write $A_j=A_{x,\delta}(G_j)$ and $L_j=\sum_{t\ge0}\alpha_{x,\delta}(t)f_{G_j}(t)$ for $j=1,2$. Set \(S=A_1+A_2\). If \(S=0\), then \(A_1=A_2=0\), and the claim is trivial. Assume \(S>0\). By the representation bound in Assumption~\ref{asmp:aa-self-normal-regular}, 
\begin{displaymath} 
|A_j-L_j|\le \varepsilon_{x,\delta}, \qquad j=1,2.
 \end{displaymath}
Hence $|A_1-A_2|\le|L_1-L_2|+2\varepsilon_{x,\delta}$. Using $(\sqrt u-\sqrt v)^2\le \frac{(u-v)^2}{u+v}$ for $u,v\ge0$, we obtain
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le\frac{2|L_1-L_2|^2}{S}+\frac{8\varepsilon_{x,\delta}^2}{S}.
\end{displaymath}
By Cauchy--Schwarz inequality
\begin{displaymath}
|L_1-L_2|^2\le\left\{\sum_{t\ge0}\alpha_{x,\delta}(t)^2(f_{G_1}(t)+f_{G_2}(t))\right\}\left\{\sum_{t\ge0}\frac{(f_{G_1}(t)-f_{G_2}(t))^2}{f_{G_1}(t)+f_{G_2}(t)}\right\}.
\end{displaymath}
By the self-normalization bound in Assumption~\ref{asmp:aa-self-normal-regular} and Lemma~\ref{lem:chi2-hell},
\begin{displaymath}
|L_1-L_2|^2\le 4C_A S\,\mathcal H(G_1,G_2).
\end{displaymath}
Therefore
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le 8C_A\,\mathcal H(G_1,G_2)+\frac{8\varepsilon_{x,\delta}^2}{S}.
\end{displaymath}
On the other hand,
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le A_1+A_2=S.
\end{displaymath}
Combining the two bounds gives
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le8C_A\,\mathcal H(G_1,G_2)+\min\left\{S,\frac{8\varepsilon_{x,\delta}^2}{S}\right\}.
\end{displaymath}
Finally, $\min\left\{S,\frac{8\varepsilon_{x,\delta}^2}{S}\right\}\le2\sqrt{2}\,\varepsilon_{x,\delta}$, which proves the result.

\label{lem:tail-X-exp-nocoarsen}
	Let ${G^\ast}\in{\sf SubE}(s)$ and let $X\mid \theta\sim\mathrm{Poi}(\theta)$, $\theta\sim {G^\ast}$. Then there exist constants $c_s>0$ and $C_s<\infty$, depending only on $s$, such that
	\begin{displaymath}
		\mathbb{P}_{{G^\ast}}(X>K)\le C_s e^{-c_s K},\qquad K\in\mathbb{Z}_+.
	\end{displaymath}
	One may take
	\begin{displaymath}
		c_s:=\log\Big(1+\frac{1}{2s}\Big),\qquad C_s:=3.
	\end{displaymath}

For every $\lambda\in(0,1/s)$,
	\begin{displaymath}
		\mathbb{E}[e^{\lambda \theta}]=1+\lambda\int_0^\infty e^{\lambda t}\,{G^\ast}((t,\infty))\,dt\le1+2\lambda\int_0^\infty e^{-(1/s-\lambda)t}\,dt=1+\frac{2\lambda s}{1-\lambda s}.
	\end{displaymath}
	Choose $\lambda=(2s)^{-1}$ to get
	\begin{displaymath}
		\mathbb{E}[e^{\theta/(2s)}]\le 3.
	\end{displaymath}
	Now let $z_s:=1+\frac{1}{2s}$ and $c_s:=\log z_s$. Since $X\mid \theta\sim\mathrm{Poi}(\theta)$,
	\begin{displaymath}
		\mathbb{E}[z_s^X\mid \theta]=\mathop{\rm exp}\big(\theta(z_s-1)\big)=e^{\theta/(2s)}.
	\end{displaymath}
	Hence
	\begin{displaymath}
		\mathbb{E}[z_s^X]\le 3.
	\end{displaymath}
	By Markov's inequality,
	\begin{displaymath}
		\mathbb{P}_{{G^\ast}}(X\ge K+1)\le z_s^{-(K+1)}\mathbb{E}[z_s^X]\le3 z_s^{-(K+1)}\le3e^{-c_s K}.
	\end{displaymath}
	This proves the claim.

\label{lem:sqrtA-control-coarse-compact}
Fix \(x\in\{1,\dots,\widehat K\}\) and \(\delta\in(0,1]\). Assume \prettyref{asmp:aa-self-normal-coarse} holds on \(\mathcal C\). Then, for all \(G_1,G_2\in\mathcal C\),
\begin{displaymath}
\left(\sqrt{A_{x,\delta}(G_1)}-\sqrt{A_{x,\delta}(G_2)}\right)^2\le 8C_A\,\mathcal H^{(T)}(G_1,G_2)+2\sqrt{2}\,\varepsilon_{x,\delta}^{(T)}.
\end{displaymath}

Write $A_j=A_{x,\delta}(G_j)$, $L_j=\sum_{t=0}^{T+1}\alpha_{x,\delta}^{(T)}(t)\widetilde f_{G_j}^{(T)}(t)$ for $j=1,2$. Set \(S=A_1+A_2\). If \(S=0\), then \(A_1=A_2=0\), and the claim is trivial. Therefore, assume \(S>0\). By the representation bound in Assumption~\ref{asmp:aa-self-normal-coarse},
\begin{displaymath}
|A_j-L_j|\le \varepsilon_{x,\delta}^{(T)},
\qquad j=1,2.
\end{displaymath}
Hence
\begin{displaymath}
|A_1-A_2|\le|L_1-L_2|+2\varepsilon_{x,\delta}^{(T)}.
\end{displaymath}
Using
\begin{displaymath}
(\sqrt u-\sqrt v)^2\le \frac{(u-v)^2}{u+v},\qquad u,v\ge0,
\end{displaymath}
we obtain
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le\frac{2|L_1-L_2|^2}{S}+\frac{8(\varepsilon_{x,\delta}^{(T)})^2}{S}.
\end{displaymath}
By Cauchy--Schwarz inequality
\begin{displaymath}
|L_1-L_2|^2\le\left\{\sum_{t=0}^{T+1}\left(\alpha_{x,\delta}^{(T)}(t)\right)^2\left(\widetilde f_{G_1}^{(T)}(t)+\widetilde f_{G_2}^{(T)}(t)\right)\right\}\left\{\sum_{t=0}^{T+1}\frac{\left(\widetilde f_{G_1}^{(T)}(t)-\widetilde f_{G_2}^{(T)}(t)\right)^2}{\widetilde f_{G_1}^{(T)}(t)+\widetilde f_{G_2}^{(T)}(t)}\right\}.
\end{displaymath}
By the self-normalization bound in Assumption~\ref{asmp:aa-self-normal-coarse} and Lemma~\ref{lem:chi2-hell}, $|L_1-L_2|^2\le4C_A S\,\mathcal H^{(T)}(G_1,G_2)$. Therefore
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le8C_A\,\mathcal H^{(T)}(G_1,G_2)+\frac{8(\varepsilon_{x,\delta}^{(T)})^2}{S}.
\end{displaymath}
On the other hand,
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le A_1+A_2=S.
\end{displaymath}
Combining the two bounds gives
\begin{displaymath}
(\sqrt{A_1}-\sqrt{A_2})^2\le8C_A\,\mathcal H^{(T)}(G_1,G_2)+\min\left\{S,\frac{8(\varepsilon_{x,\delta}^{(T)})^2}{S}\right\}.
\end{displaymath}
Finally, $\min\left\{S,\frac{8(\varepsilon_{x,\delta}^{(T)})^2}{S}\right\}\le2\sqrt{2}\,\varepsilon_{x,\delta}^{(T)}$. This proves the lemma.

\label{lem:exact-A-representation-discrete-above}
For each \(x=1,\dots,K_J\), there exist constants \(\alpha_x(0),\dots,\alpha_x(J-1)\), depending only on \(\Theta_J\), such that
\begin{displaymath}
A_x(G)=\sum_{t=0}^{J-1}\alpha_x(t)f_G(t),\qquad G\in\mathcal P(\Theta_J).
\end{displaymath}

For \(G\in\mathcal P(\Theta_J)\), the vector \((q_G(0),\dots,q_G(J-1))^\top\) satisfies $q_G=Vv_G$. Hence \(v_G=V^{-1}q_G\). For fixed \(x=1,\dots,K_J\),
\begin{displaymath}
A_x(G)=\sum_{j:\theta_j<x}\theta_j^x v_G(j).
\end{displaymath}
Thus \(A_x(G)\) is a linear functional of \(q_G\). Since \(q_G(t)=t!f_G(t)\), there are constants \(\alpha_x(0),\dots,\alpha_x(J-1)\), depending only on \(\Theta_J\), such that
\begin{displaymath}
A_x(G)=\sum_{t=0}^{J-1}\alpha_x(t)f_G(t).
\end{displaymath}
This proves the claim.

\label{lem:ratio-control-discrete-above}
For all \(G_1,G_2\in\mathcal C\), there exists a constant \(C_{\Theta_J}<\infty\), depending only on \(({\Theta_J},b_J)\), such that
\begin{displaymath}
\sum_{x=1}^{K_J} f_{G_1}(x)\bigl(m_{G_1}(x)-m_{G_2}(x)\bigr)^2\le C_{\Theta_J} H^2(f_{G_1},f_{G_2}).
\end{displaymath}
Moreover, if \(T\ge T_J\), then there exists a constant \(C_{{\Theta_J},T,b_J}<\infty\), depending only on \(({\Theta_J},T,b_J)\), such that
\begin{displaymath}
\sum_{x=1}^{K_J} f_{G_1}(x)\bigl(m_{G_1}(x)-m_{G_2}(x)\bigr)^2\le C_{{\Theta_J},T,b_J}H^2\!\left(\widetilde f_{G_1}^{(T)},\widetilde f_{G_2}^{(T)}\right).
\end{displaymath}

Fix \(x=1,\dots,K_J\). For \(r=1,2\), write $A_r=A_x(G_r)$ and $B_r=B_x(G_r)=x!f_{G_r}(x)$. Since \(G_1,G_2\in\mathcal C\),
\begin{displaymath}
B_r\ge x!b_J,\qquad r=1,2.
\end{displaymath}
Also \(0\le A_r\le B_r\). Hence
\begin{equation}\label{eq:discrete-ratio-direct}
\left|\frac{A_1}{B_1}-\frac{A_2}{B_2}\right|\le\frac{|A_1-A_2|}{B_1}+\frac{A_2|B_1-B_2|}{B_1B_2}\le\frac{|A_1-A_2|}{x!b_J}+\frac{|B_1-B_2|}{x!b_J}.
\end{equation}
By Lemma~\ref{lem:exact-A-representation-discrete-above},
\begin{displaymath}
A_1-A_2=\sum_{t=0}^{J-1}\alpha_x(t)\bigl(f_{G_1}(t)-f_{G_2}(t)\bigr).
\end{displaymath}
Therefore, by Cauchy--Schwarz and the elementary inequality \((a-b)^2\le4(\sqrt a-\sqrt b)^2\) for \(a,b\in[0,1]\),
\begin{displaymath}
|A_1-A_2|^2\le C_{{\Theta_J},x}H^2(f_{G_1},f_{G_2}),
\end{displaymath}
for a finite constant \(C_{{\Theta_J},x}\) depending only on \({\Theta_J}\). Similarly,
\begin{displaymath}
|B_1-B_2|^2=(x!)^2|f_{G_1}(x)-f_{G_2}(x)|^2\le 4(x!)^2H^2(f_{G_1},f_{G_2}).
\end{displaymath}
Combining these bounds with ~(\ref{eq:discrete-ratio-direct}), we obtain $\bigl(m_{G_1}(x)-m_{G_2}(x)\bigr)^2\le C_{{\Theta_J},b_J,x}H^2(f_{G_1},f_{G_2})$. Multiplying by \(f_{G_1}(x)\le1\) and summing over \(x=1,\dots,K_J\) gives
the first assertion.

For the coarsened assertion, assume \(T\ge T_J=\max\{K_J,J-1\}\). Then the coordinates
\(0,\dots,J-1\) and \(1,\dots,K_J\) all belong to the non-tail part of the
\(T\)-coarsened alphabet. Hence the preceding bounds remain valid with
\(H^2(f_{G_1},f_{G_2})\) replaced by
\(H^2(\widetilde f_{G_1}^{(T)},\widetilde f_{G_2}^{(T)})\). This proves the lemma.
